import { Router } from "express";
import { cartTotal } from "../cart/totals.js";
import { paymentError } from "../payments/errors.js";

export const checkout = Router();

checkout.post("/", async (req, res) => {
  const { items, card } = req.body;
  try {
    const total = cartTotal(items);
    res.json({ total, status: "paid" });
  } catch (error) {
    res.status(402).json(paymentError(error));
  }
});

import { Router } from "express";
import { db } from "../db.js";

export const orders = Router();

orders.get("/", async (req, res) => res.json(await db.orders.list()));
orders.get("/:id", async (req, res) => res.json(await db.orders.find(req.params.id)));
orders.post("/", async (req, res) => res.status(201).json(await db.orders.create(req.body)));

import { Router } from "express";
import { db } from "../db.js";

export const products = Router();

products.get("/", async (req, res) => {
  res.json(await db.products.list());
});

export function cartTotal(items, { discount = 0, taxRate = 0.1 } = {}) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.quantity, 0);
  const discounted = subtotal * (1 - discount);
  return Math.round(discounted * (1 + taxRate) * 100) / 100;
}

export function paymentError(error) {
  return { error: error.code ?? "payment_failed", message: error.message };
}

