  it("applies a discount before tax", () => {
    expect(cartTotal([{ price: 100, quantity: 1 }], { discount: 0.2 })).toBe(88);
  });

  it("adds tax", () => {
    expect(cartTotal([{ price: 10, quantity: 3 }])).toBe(33);
  });

  it("is 0 for an empty cart", () => {
    expect(cartTotal([])).toBe(0);
  });
});

